    public static double predict(double[] x) {
        if (x.length != CpuFeatureExtractor.FEATURE_COUNT) {
            throw new IllegalArgumentException("N-GOD特徴量数が一致しません");
        }
        double[] h1 = denseRelu(x, W1, B1, 32);
        double[] h2 = denseRelu(h1, W2, B2, 16);
        double z = B3[0];
        for (int i = 0; i < 16; i++) z += W3[i] * h2[i];
        return 1.0 / (1.0 + Math.exp(-z));
    }

    private static double[] denseRelu(double[] input, double[] weights, double[] bias, int outputSize) {
        int inputSize = input.length;
        double[] out = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double v = bias[o];
            int base = o * inputSize;
            for (int i = 0; i < inputSize; i++) v += weights[base + i] * input[i];
            out[o] = Math.max(0.0, v);
        }
        return out;
    }
